select os_date
from ${database.prefix.order}hou_order_settlement
where shop_id = #{shopId}
  and os_order_type = #{osOrderType}
order by os_datetime desc
limit 1

select sum(if(pay_way_id != 4, pay_total_amount, 0)) as orderPaymentAmount,
       sum(order_commission_fee)                     as orderCommissionFee,
       sum(discount_amount)                          as baseMemberDiscount
from ${database.prefix.webpos}hou_wps_order
where shop_id = #{param.shopId}
  and order_is_settlement = 0
  and order_status in (1, 2, 3)
  and pay_time >= #{param.start}
  and pay_time <= #{param.end}

select sum(if(pay_way_id != 4, pay_total_amount, 0)) as orderPaymentAmount,
       sum(order_commission_fee)                     as orderCommissionFee,
       sum(discount_amount)                          as baseMemberDiscount
from ${database.prefix.webpos}hou_wps_order
where shop_id = #{param.shopId}
  and order_is_settlement = 0
  and order_status = 3
  and refund_status = 1
  and refund_time >= #{param.start}
  and refund_time <= #{param.end}

select order_no
from ${database.prefix.webpos}hou_wps_order
where shop_id = #{param.shopId}
  and order_is_settlement = 0
  and order_status in (1, 2)
  and refund_status = 0
  and pay_time >= #{param.start}
  and pay_time <= #{param.end}

select order_no
from ${database.prefix.webpos}hou_wps_order
where shop_id = #{param.shopId}
  and order_is_settlement = 0
  and order_status = 3
  and refund_status = 1
  and pay_time >= #{param.start}
  and pay_time <= #{param.end}

